/** A native EXISTS stops at the first accepted result, not the first input record tested by its filter. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeFilteredExistsBoundTest {

	private static final int INPUT_ROWS = 100;
	private static final long ROOT = iri(1);
	private static final long OUTER = iri(2);
	private static final long OTHER = iri(3);
	private static final long WITNESS = iri(4);
	private static final long GRAPH = iri(5);
	private final Map<String, String> previous = new LinkedHashMap<>();

	@BeforeEach
	void configurePhysicalRoute() {
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, "true");
		set(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, "false");
		set(LmdbNativeKernelLowering.ROW_EXISTS_PROPERTY, "true");
		set(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "true");
		set(SubplanMarkProbe.ENABLED_PROPERTY, "false");
		set("rdf4j.lmdb.membership.impl", "hash");
	}

	@AfterEach
	void restoreProperties() {
		previous.forEach((key, value) -> {
			if (value == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, value);
			}
		});
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, INPUT_ROWS, -1 })
	void nativeFilteredWitnessCeilingIncludesRowsBeforeItsFirstMatch(int acceptedOrdinal) {
		CountingSource source = new CountingSource();
		RowState row = row(source);
		AtomicInteger predicateCalls = new AtomicInteger();
		try {
			NativeBooleanFilter innerFilter = new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState input) {
					predicateCalls.incrementAndGet();
					return acceptedOrdinal > 0 && input.slots[1] == object(acceptedOrdinal);
				}

				@Override
				public long batchReadMask() {
					return 1L << 1;
				}
			};
			PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(WITNESS), Term.slot(1),
					Term.constant(GRAPH), ContextConstraint.UNRESTRICTED, true, null, "", null,
					INPUT_ROWS, source.indexAccessProfile());
			SlotPlan body = new FilterPlan(pattern, innerFilter, 1L << 1);
			ExistsFilter exists = new ExistsFilter(body);
			assertThat(exists.existsPlan).as("the real native cursor retains the filter as a trailing predicate")
					.isNotNull();
			assertThat(exists.existsPlan.trailingFilters).containsExactly(innerFilter);
			NativeBooleanFilter ordinary = new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState ignored) {
					return false;
				}

				@Override
				public long batchReadMask() {
					return 0L;
				}
			};
			// Positive OR is a proven whole native-hook route, independent of direct witness binding heuristics.
			NativeBooleanFilter condition = new BooleanCombinationFilter(exists, ordinary, false);
			SlotPlan input = new UnionPlan(outerPattern(source, OUTER), outerPattern(source, OTHER));
			FilterPlan admittedPlan = new FilterPlan(input, condition, 1L);
			assertNativeHookAdmission(admittedPlan, condition, row);
			assertThat(source.recordReads).isZero();
			assertThat(predicateCalls).hasValue(0);

			// Price one invocation of the same admitted hook, excluding unrelated outer producer work.
			row.slots[0] = ROOT;
			row.recomputeBoundMask();
			LmdbNativeCostVector fullBody = LmdbNativePlanExecutionProfile.profile(body, row, row.boundMask(),
					LmdbNativePlanExecutionProfile.Mode.SEQUENTIAL);
			LmdbNativeCostVector probe = LmdbNativePlanExecutionProfile.kernelVector(
					new FilterPlan(SingletonPlan.INSTANCE, condition, 1L), row, row.boundMask(),
					Feature.INTERPRETED_ROW);
			assertThat(fullBody.high(Feature.SCANNED_ROW)).isGreaterThanOrEqualTo(INPUT_ROWS);
			assertThat(source.recordReads).as("quoting must not run the cursor").isZero();
			assertThat(predicateCalls).hasValue(0);

			assertThat(condition.accept(row)).isEqualTo(acceptedOrdinal > 0);
			int examined = acceptedOrdinal > 0 ? acceptedOrdinal : INPUT_ROWS;
			assertThat(source.recordReads).as("raw records pulled before the first accepted witness")
					.isEqualTo(examined);
			assertThat(predicateCalls).hasValue(examined);
			assertThat(source.closes).as("the first-match cursor is closed on success and exhaustion").isEqualTo(1);
			assertThat(row.slots[0]).isEqualTo(ROOT);
			assertThat(probe.expected(Feature.SCANNED_ROW))
					.as("the expected first-match heuristic may remain below the complete run")
					.isBetween(0D, fullBody.high(Feature.SCANNED_ROW));
			assertThat(probe.high(Feature.SCANNED_ROW))
					.as("one output does not bound rejected input records; expected=%s, actual=%s",
							probe.expected(Feature.SCANNED_ROW), source.recordReads)
					.isGreaterThanOrEqualTo(source.recordReads);
			assertThat(probe.high(Feature.INTERPRETED_ROW))
					.as("every rejected record also executes its native predicate")
					.isGreaterThanOrEqualTo(predicateCalls.get());
		} finally {
			row.memoryScope.close();
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, INPUT_ROWS, -1 })
	void placedJoinFilterCeilingIncludesRejectedWitnessRows(int acceptedOrdinal) {
		CountingSource source = new CountingSource(true);
		RowState row = row(source);
		AtomicInteger predicateCalls = new AtomicInteger();
		try {
			NativeBooleanFilter placed = new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState input) {
					predicateCalls.incrementAndGet();
					return acceptedOrdinal > 0 && input.slots[1] == object(acceptedOrdinal);
				}

				@Override
				public long batchReadMask() {
					return 1L << 1;
				}
			};
			PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(WITNESS), Term.slot(1),
					Term.constant(GRAPH), ContextConstraint.UNRESTRICTED, true, null, "", null,
					INPUT_ROWS, source.indexAccessProfile());
			PatternPlan anchor = new PatternPlan(Term.slot(0), Term.constant(OTHER), Term.slot(2),
					Term.constant(GRAPH), ContextConstraint.UNRESTRICTED, true, null, "", null,
					1D, source.indexAccessProfile());
			MultiJoinPlan body = new MultiJoinPlan(new SlotPlan[] { pattern, anchor },
					new MaskedFilter[] { new MaskedFilter(placed, 1L << 1) });
			ExistsFilter exists = new ExistsFilter(body);
			assertThat(exists.existsPlan).isNotNull();
			assertThat(exists.existsPlan.join).isSameAs(body);
			assertThat(exists.existsPlan.trailingFilters).isEmpty();
			NativeBooleanFilter ordinary = new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState ignored) {
					return false;
				}

				@Override
				public long batchReadMask() {
					return 0L;
				}
			};
			NativeBooleanFilter condition = new BooleanCombinationFilter(exists, ordinary, false);
			SlotPlan input = new UnionPlan(outerSubjectPattern(source, OUTER), outerSubjectPattern(source, OTHER));
			FilterPlan admittedPlan = new FilterPlan(input, condition, 1L);
			assertNativeHookAdmission(admittedPlan, condition, row);
			assertThat(row.boundMask()).isZero();
			assertThat(input.producedMask()).isEqualTo(1L);
			assertThat(body.derivedPlan(input.producedMask()).order[0].producedMask() & 1L)
					.as("the witness chain starts with a child correlated to the outer-produced subject")
					.isEqualTo(1L);
			LmdbNativeCostVector quote = LmdbNativePlanExecutionProfile.kernelVector(admittedPlan, row,
					row.boundMask(), Feature.INTERPRETED_ROW);
			assertThat(source.recordReads).as("physical planning and quoting must not run the witness").isZero();
			assertThat(predicateCalls).hasValue(0);

			row.slots[0] = ROOT;
			row.recomputeBoundMask();
			assertThat(condition.accept(row)).isEqualTo(acceptedOrdinal > 0);
			int examined = acceptedOrdinal > 0 ? acceptedOrdinal : INPUT_ROWS;
			assertThat(source.witnessReads).isEqualTo(examined);
			assertThat(predicateCalls).hasValue(examined);
			assertThat(source.recordReads).isBetween(examined, examined + 1);
			assertThat(source.opens).isPositive();
			assertThat(source.closes).isEqualTo(source.opens);
			assertThat(quote.high(Feature.SCANNED_ROW))
					.as("the complete admitted quote must cover even one actual filtered witness invocation")
					.isGreaterThanOrEqualTo(source.recordReads);
			assertThat(quote.high(Feature.INTERPRETED_ROW))
					.as("a filter placed inside MultiJoinPlan can run on every rejected candidate")
					.isGreaterThanOrEqualTo(predicateCalls.get());
		} finally {
			row.memoryScope.close();
		}
	}

	private static void assertNativeHookAdmission(FilterPlan plan, NativeBooleanFilter condition, RowState row) {
		try (LmdbNativeStrategyProposal<RowCursor> proposal = LmdbNativeKernelExecution.proposeRows(plan, row,
				null, true)) {
			assertThat(proposal).isNotNull();
			LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(plan, row, null, false);
			assertThat(lowered).isNotNull();
			List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
			LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
			assertThat(nodes).anyMatch(LmdbNativeKernelIr.FilterValue.class::isInstance)
					.noneMatch(LmdbNativeKernelIr.Exists.class::isInstance);
			assertThat(lowered.bindings.filterHooks).singleElement()
					.satisfies(hook -> assertThat(hook.source.filter).isSameAs(condition));
			assertThat(lowered.kernel.resumable).isTrue();
			JaninoKernel kernel = LmdbNativeKernelInterpreter.forRows(lowered.kernel);
			assertThat(kernel).isNotNull();
			kernel.close();
		}
	}

	private static PatternPlan outerPattern(CountingSource source, long predicate) {
		return new PatternPlan(Term.slot(0), Term.constant(predicate), Term.slot(2), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, 1D, source.indexAccessProfile());
	}

	private static PatternPlan outerSubjectPattern(CountingSource source, long predicate) {
		return new PatternPlan(Term.slot(0), Term.constant(predicate), Term.constant(object(0)), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, 1D, source.indexAccessProfile());
	}

	private static long object(int ordinal) {
		return iri(100 + ordinal);
	}

	private static long iri(int ordinal) {
		return (long) ordinal << 7 | 1L << 1;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}

	private static final class CountingSource implements NativeLmdbQuerySource {
		private final IndexAccessProfile profile;
		private final boolean includeAnchor;
		int recordReads;
		int witnessReads;
		int opens;
		int closes;

		CountingSource() {
			this(false);
		}

		CountingSource(boolean includeAnchor) {
			this.includeAnchor = includeAnchor;
			int[][] prefixes = new int[StatementOrder.values().length + 1][16];
			for (int[] prefix : prefixes) {
				for (int mask = 0; mask < prefix.length; mask++) {
					prefix[mask] = mask;
				}
			}
			profile = new IndexAccessProfile(INPUT_ROWS + (includeAnchor ? 1 : 0), 1, prefixes, false,
					-1L, -1L, -1L);
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return profile;
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return OptionalDouble.of(predicate == WITNESS ? INPUT_ROWS : 1D);
		}

		@Override
		public RecordIterator statements(long subject, long predicate, long object, long context) {
			opens++;
			return new RecordIterator() {
				int ordinal;
				boolean closed;

				@Override
				public long[] next() {
					while (++ordinal <= INPUT_ROWS + (includeAnchor ? 1 : 0)) {
						boolean anchor = ordinal > INPUT_ROWS;
						long recordPredicate = anchor ? OTHER : WITNESS;
						long value = object(anchor ? 0 : ordinal);
						if ((subject == UNKNOWN_ID || subject == ROOT)
								&& (predicate == UNKNOWN_ID || predicate == recordPredicate)
								&& (object == UNKNOWN_ID || object == value)
								&& (context == UNKNOWN_ID || context == GRAPH)) {
							recordReads++;
							if (!anchor) {
								witnessReads++;
							}
							return new long[] { ROOT, recordPredicate, value, GRAPH };
						}
					}
					return null;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						closes++;
					}
				}
			};
		}

		@Override
		public long idOf(Value value) {
			return UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return SimpleValueFactory.getInstance().createIRI("urn:filtered-exists:" + id);
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public long count(long subject, long predicate, long object, long context) {
			throw new AssertionError("the first-match witness must consume a real record cursor");
		}

		@Override
		public boolean has(long subject, long predicate, long object, long context) {
			throw new AssertionError("the filtered witness cannot be answered by an unfiltered existence probe");
		}

		@Override
		public double estimate(long subject, long predicate, long object, long context) {
			return INPUT_ROWS;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}
	}
}
